    bit = [0] * (size + 1)
    for i in range(1, M + 1):
        bit[i] = i & -i

    step = 1
    while step * 2 <= size:
        step *= 2

    def lower_bound(target):
        pos = 0
        acc = 0
        k = step
        while k:
            nxt = pos + k
            if nxt <= size and acc + bit[nxt] < target:
                pos = nxt
                acc += bit[nxt]
            k >>= 1
        return pos + 1

    def add(i, v):
        while i <= size:
            bit[i] += v
            i += i & -i

    def prefix(i):
        s = 0
        while i:
            s += bit[i]
            i -= i & -i
        return s

    for _ in range(N):
        L = data[p]
        R = data[p + 1]
        p += 2

        lo = lower_bound(L)
        hi = lower_bound(R + 1) - 1

        if hi > M:
            hi = M

        if lo <= hi:
            add(lo, 1)
            add(hi + 1, -1)

    Q = data[p]
